-- SELECT only. Run after apply. 예/아니오 항목은 모두 예, 그 밖의 값은 precheck의 같은 이름 항목과 같은 값이어야 한다
-- (소식 표의 줄 수·표 권한·정책·칸 권한 해시 변화 없음).
select 'history row present' as item,case when (select count(*) from supabase_migrations.schema_migrations where version='20261025210000' and name='feed_item_archive')=1 then '예' else '아니오' end as value
union all select 'new column present, empty, no default, no column privilege for anyone',case when (select count(*) from pg_attribute a where a.attrelid=to_regclass('public.app_feed_items') and not a.attisdropped and a.attname='archived_at' and not a.attnotnull and not a.atthasdef and a.atttypid='timestamptz'::regtype and a.attacl is null)=1 and not exists(select 1 from public.app_feed_items where archived_at is not null) then '예' else '아니오' end
union all select 'new index present (partial on archived_at)',case when exists(select 1 from pg_index i join pg_class ic on ic.oid=i.indexrelid where i.indrelid=to_regclass('public.app_feed_items') and ic.relname='app_feed_items_archived_idx' and i.indpred is not null) then '예' else '아니오' end
union all select 'function: definer, empty search_path, execute only authenticated',case when exists(select 1 from pg_proc p where p.oid=to_regprocedure('public.app_feed_set_state(uuid,text)') and p.prosecdef and p.proconfig=array['search_path=""'] and has_function_privilege('authenticated',p.oid,'execute') and not has_function_privilege('anon',p.oid,'execute') and not has_function_privilege('service_role',p.oid,'execute') and coalesce(p.proacl::text,'')!~'(^|[{,])=') then '예' else '아니오' end
union all select 'authenticated and service_role cannot write or read the new column directly',case when not has_column_privilege('authenticated','public.app_feed_items','archived_at','update') and not has_column_privilege('authenticated','public.app_feed_items','archived_at','insert') and not has_column_privilege('service_role','public.app_feed_items','archived_at','insert') and not has_column_privilege('service_role','public.app_feed_items','archived_at','update') and not has_column_privilege('service_role','public.app_feed_items','archived_at','select') then '예' else '아니오' end
union all select 'feed items: no insert or delete, hidden_at update kept, trigger and one policy',case when not has_table_privilege('authenticated','public.app_feed_items','insert') and not has_table_privilege('authenticated','public.app_feed_items','delete') and has_column_privilege('authenticated','public.app_feed_items','hidden_at','update') and (select count(*) from pg_trigger where tgrelid=to_regclass('public.app_feed_items') and not tgisinternal)>=1 and (select count(*) from pg_policy where polrelid=to_regclass('public.app_feed_items'))=1 then '예' else '아니오' end
union all select 'no anon or PUBLIC table or column privilege',case when not exists(select 1 from pg_class where oid=to_regclass('public.app_feed_items') and coalesce(relacl::text,'')~'(^|[{,])(anon)?=') and not exists(select 1 from pg_attribute where attrelid=to_regclass('public.app_feed_items') and attacl::text~'(^|[{,])(anon)?=') then '예' else '아니오' end
union all select 'feed items rows',(select count(*)::text from public.app_feed_items)
union all select 'feed table grants policies hash',md5(coalesce((select string_agg(c.relname||':'||c.relrowsecurity::text||':'||coalesce(c.relacl::text,''),',' order by c.relname) from pg_class c where c.oid in(to_regclass('public.app_feed_items'),to_regclass('public.app_feed_days'))),'')
  ||coalesce((select string_agg(a.attname::text||':'||a.attacl::text,',' order by a.attname) from pg_attribute a where a.attrelid=to_regclass('public.app_feed_items') and a.attnum>0 and not a.attisdropped and a.attacl is not null),'')
  ||coalesce((select string_agg(p.polname::text||p.polcmd::text||p.polroles::text||coalesce(pg_get_expr(p.polqual,p.polrelid),'')||coalesce(pg_get_expr(p.polwithcheck,p.polrelid),''),',' order by p.polname) from pg_policy p where p.polrelid in(to_regclass('public.app_feed_items'),to_regclass('public.app_feed_days'))),''));
